function countPins(n: number): number {
  const MOD = 1_000_000_007n;
  const power = (base: bigint, exp: bigint): bigint => {
    let result = 1n;
    base %= MOD;
    while (exp > 0n) {
      if (exp & 1n) result = (result * base) % MOD;
      base = (base * base) % MOD;
      exp >>= 1n;
    }
    return result;
  };
  const N = BigInt(n);
  return Number((power(5n, (N + 1n) / 2n) * power(4n, N / 2n)) % MOD);
}

